export const QUESTIONS=[
/* ===== Panneaux ===== */
{t:"panneaux",i:{s:"B1"},q:"Que signifie ce signal ?",a:["Céder le passage","Arrêt obligatoire (STOP)","Route prioritaire"],r:0,e:"Signal B1 : vous devez céder le passage aux usagers qui circulent sur la voie que vous allez aborder. Vous ne vous arrêtez que si c'est nécessaire."},
{t:"panneaux",i:{s:"B1"},q:"À ce signal, devez-vous toujours vous arrêter ?",a:["Non, seulement si c'est nécessaire pour céder le passage","Oui, toujours, même si la voie est libre"],r:0,e:"Contrairement au STOP, le B1 n'impose pas l'arrêt. Vous ralentissez et vous vous arrêtez seulement si un usager prioritaire arrive."},
{t:"panneaux",i:{s:"B5"},q:"Que devez-vous faire à ce signal ?",a:["Marquer l'arrêt complet, puis céder le passage","Ralentir et passer si la voie est libre","M'arrêter uniquement si un véhicule arrive"],r:0,g:1,e:"STOP (B5) : arrêt complet obligatoire à la ligne d'arrêt ou, à défaut, à la limite de la chaussée abordée, même si aucun véhicule n'arrive. Ensuite, vous cédez le passage."},
{t:"panneaux",i:{s:"B9"},q:"Ce signal indique…",a:["Que vous circulez sur une route prioritaire","La fin d'une route prioritaire","Un carrefour où la priorité de droite s'applique"],r:0,e:"B9 : route prioritaire. Aux carrefours, les usagers venant des voies latérales doivent vous céder le passage. La règle vaut jusqu'au signal B11."},
{t:"panneaux",i:{s:"B11"},q:"Ce signal indique…",a:["La fin de la route prioritaire","Le début d'une route prioritaire","Une interdiction de dépasser"],r:0,e:"B11 : fin de la route prioritaire. Aux carrefours suivants, la priorité est réglée par d'autres signaux ou, à défaut, par la priorité de droite."},
{t:"panneaux",i:{s:"B15"},q:"Ce signal annonce…",a:["Que vous avez la priorité au prochain carrefour","Un carrefour où la priorité de droite s'applique","Un passage à niveau"],r:0,e:"B15 : vous êtes prioritaire au prochain carrefour seulement. Les usagers des autres voies doivent vous céder le passage."},
{t:"panneaux",i:{s:"B17"},q:"Ce signal annonce…",a:["Un carrefour où la priorité de droite s'applique","Un passage à niveau sans barrières","Une route prioritaire"],r:0,e:"B17 : au prochain carrefour, vous cédez le passage aux usagers venant de votre droite."},
{t:"panneaux",i:{s:"A51"},q:"Que signifie ce signal ?",a:["Un danger, le plus souvent précisé par un panneau additionnel","Une interdiction générale","Un endroit où il faut klaxonner"],r:0,e:"A51 : « autre danger ». La nature du danger est en général indiquée sur un panneau additionnel."},
{t:"panneaux",i:{s:"A33"},q:"Ce signal annonce…",a:["Des feux de signalisation","Un passage pour piétons","Un carrefour à sens giratoire"],r:0,e:"A33 : signal de danger qui annonce des feux de signalisation."},
{t:"panneaux",i:{s:"A1a"},q:"Ce signal annonce…",a:["Un virage dangereux à gauche","Une obligation de tourner à gauche","Une descente dangereuse"],r:0,e:"A1a : virage dangereux vers la gauche. Adaptez votre vitesse avant le virage, pas dedans."},
{t:"panneaux",i:{s:"A45"},q:"Ce signal, placé juste avant les rails, indique…",a:["Un passage à niveau sans barrières, à une seule voie ferrée","Un carrefour dangereux","Une interdiction de stationner"],r:0,e:"La croix de Saint-André signale un passage à niveau sans barrières. Une croix simple indique une seule voie ferrée, une croix double plusieurs voies."},
{t:"panneaux",i:{s:"C1"},q:"Ce signal est placé à l'entrée d'une rue. Pouvez-vous y entrer en voiture ?",a:["Non","Oui, si je roule lentement","Oui, si c'est pour me garer"],r:0,g:1,e:"C1 : accès interdit à tout conducteur dans ce sens (sens interdit). Un panneau additionnel peut autoriser certains usagers, par exemple les cyclistes."},
{t:"panneaux",i:{s:"C3"},q:"Que signifie ce signal ?",a:["Accès interdit dans les deux sens à tout conducteur","Voie à sens unique","Fin de toutes les interdictions"],r:0,e:"C3 : accès interdit, dans les deux sens, à tout conducteur. Des exceptions (riverains, livraisons…) peuvent figurer sur un panneau additionnel."},
{t:"panneaux",i:{s:"C43",v:"50"},q:"Que signifie ce signal ?",a:["Vitesse maximale autorisée : 50 km/h","Vitesse conseillée : 50 km/h","Vitesse minimale obligatoire : 50 km/h"],r:0,e:"C43 : limitation de vitesse. Vous ne pouvez pas dépasser la vitesse indiquée, et vous roulez moins vite si les circonstances l'exigent."},
{t:"panneaux",i:{s:"C45",v:"70"},q:"Que signifie ce signal ?",a:["Fin de la limitation de vitesse à 70 km/h","Vitesse minimale de 70 km/h","Vitesse maximale de 70 km/h"],r:0,e:"C45 : fin de la limitation. La vitesse maximale redevient celle de la règle générale (agglomération, hors agglomération…)."},
{t:"panneaux",i:{s:"C35"},q:"Après ce signal, pouvez-vous dépasser un cycliste ?",a:["Oui, l'interdiction vise les véhicules à plus de deux roues","Non, aucun dépassement n'est permis","Oui, mais seulement en agglomération"],r:0,e:"C35 interdit de dépasser par la gauche les véhicules à plus de deux roues et les véhicules attelés. Dépasser un vélo ou une moto reste permis, en sécurité et sans franchir de ligne continue."},
{t:"panneaux",i:{s:"C35"},q:"Après ce signal, pouvez-vous dépasser une voiture qui roule lentement ?",a:["Non","Oui, si la route est dégagée"],r:0,g:1,e:"C35 : interdiction de dépasser par la gauche les véhicules à plus de deux roues. Une voiture a quatre roues : le dépassement est interdit."},
{t:"panneaux",i:{s:"C37"},q:"Que signifie ce signal ?",a:["Fin de l'interdiction de dépasser","Interdiction de dépasser pour les camions","Route à deux bandes"],r:0,e:"C37 : fin de l'interdiction de dépasser imposée par le C35."},
{t:"panneaux",i:{s:"C31"},q:"Que signifie ce signal ?",a:["Interdiction de tourner à gauche","Obligation de tourner à gauche","Virage dangereux à gauche"],r:0,g:1,e:"Cercle à bord rouge : c'est une interdiction. Ici, il est interdit de tourner à gauche."},
{t:"panneaux",i:{s:"C33"},q:"Que signifie ce signal ?",a:["Interdiction de faire demi-tour","Obligation de faire demi-tour","Route en lacets"],r:0,e:"C33 : il est interdit de faire demi-tour."},
{t:"panneaux",i:{s:"D1"},q:"Que signifie ce signal ?",a:["Obligation de suivre la direction indiquée par la flèche","Direction conseillée","Voie à sens unique"],r:0,e:"Les signaux ronds à fond bleu sont des obligations. D1 : vous devez suivre la direction de la flèche."},
{t:"panneaux",i:{s:"D5"},q:"Que signifie ce signal ?",a:["Carrefour à sens giratoire : suivre le sens des flèches","Demi-tour autorisé","Boucle réservée aux bus"],r:0,e:"D5 : rond-point. Vous circulez dans le sens des flèches et vous cédez le passage aux usagers qui roulent déjà sur l'anneau."},
{t:"panneaux",i:{s:"D7"},q:"Que signifie ce signal ?",a:["Piste cyclable obligatoire pour les cyclistes","Endroit fréquenté par des cyclistes","Accès interdit aux cyclistes"],r:0,e:"D7 : piste cyclable obligatoire. Les automobilistes ne peuvent ni y circuler ni s'y arrêter. Un endroit fréquenté par des cyclistes est annoncé par un triangle de danger."},
{t:"panneaux",i:{s:"E1"},q:"Que signifie ce signal ?",a:["Stationnement interdit","Arrêt et stationnement interdits","Accès interdit"],r:0,e:"E1 (une barre) : stationnement interdit, l'arrêt reste permis. E3 (une croix) interdit l'arrêt et le stationnement."},
{t:"panneaux",i:{s:"E3"},q:"Que signifie ce signal ?",a:["Arrêt et stationnement interdits","Stationnement interdit, arrêt permis","Fin du stationnement payant"],r:0,e:"E3 : arrêt et stationnement interdits du côté de la voie où le signal est placé."},
{t:"panneaux",i:{s:"E1"},q:"Sous ce signal, pouvez-vous vous arrêter pour faire descendre un passager ?",a:["Oui","Non"],r:0,e:"E1 interdit le stationnement, pas l'arrêt. Faire descendre un passager est un arrêt, à condition de ne pas gêner."},
{t:"panneaux",i:{s:"E9a"},q:"Que signifie ce signal ?",a:["Parking : stationnement autorisé","Poste de police","Parking réservé aux bus"],r:0,e:"E9a : stationnement autorisé. Des panneaux additionnels peuvent limiter la durée ou réserver les places."},
{t:"panneaux",i:{s:"F19"},q:"Que signifie ce signal ?",a:["Voie publique à sens unique","Obligation d'aller tout droit","Route prioritaire"],r:0,e:"F19 (carré bleu) : voie à sens unique, signal d'indication. Ne le confondez pas avec le rond bleu D1, qui est une obligation."},
{t:"panneaux",i:{s:"F45"},q:"Que signifie ce signal ?",a:["Voie sans issue","Fin de l'autoroute","Interdiction de tourner"],r:0,e:"F45 : impasse. La rue ne permet pas de continuer."},
{t:"panneaux",i:{s:"Z30"},q:"Que signifie ce signal ?",a:["Début d'une zone où la vitesse est limitée à 30 km/h","Vitesse conseillée de 30 km/h sur 30 m","Zone de stationnement de 30 minutes"],r:0,e:"Zone 30 : la limitation vaut dans toute la zone, jusqu'au signal de fin de zone."},
{t:"panneaux",i:{s:"F5"},q:"Que signifie ce signal ?",a:["Début d'une autoroute","Pont mobile","Fin d'une route pour automobiles"],r:0,e:"F5 : début de l'autoroute. Ses règles propres s'appliquent : vitesse minimale, accès interdit à certains usagers, demi-tour interdit…"},
{t:"panneaux",q:"Que signale en général un panneau triangulaire à bord rouge, pointe vers le haut ?",a:["Un danger","Une obligation","Une indication"],r:0,e:"Les signaux de danger (série A) sont triangulaires, à bord rouge, pointe vers le haut."},
{t:"panneaux",q:"Un panneau rond à fond bleu est un signal…",a:["D'obligation","D'interdiction","De danger"],r:0,e:"Rond à fond bleu : obligation (série D). Rond à bord rouge : interdiction (série C)."},
{t:"panneaux",q:"Un panneau rond à fond blanc et bord rouge est en général un signal…",a:["D'interdiction","D'obligation","D'indication"],r:0,e:"Les signaux d'interdiction (série C) sont ronds, à bord rouge."},
{t:"panneaux",q:"Un panneau carré ou rectangulaire à fond bleu est en général un signal…",a:["D'indication","D'interdiction","De danger"],r:0,e:"Les signaux d'indication (série F) sont carrés ou rectangulaires, souvent à fond bleu."},
{t:"panneaux",q:"Hors agglomération, à quelle distance environ un signal de danger est-il placé avant l'endroit dangereux ?",a:["50 m","150 m","500 m"],r:1,e:"Hors agglomération, les signaux de danger sont placés à environ 150 m du danger. Une autre distance peut figurer sur un panneau additionnel."},
{t:"panneaux",q:"À quoi sert un panneau additionnel placé sous un signal ?",a:["À préciser ou limiter la portée du signal","À annuler le signal","À donner une information touristique"],r:0,e:"Le panneau additionnel précise la portée du signal : distance, durée, catégorie d'usagers, exceptions…"},

/* ===== Feux et agents ===== */
{t:"feux",i:{l:"red"},q:"Le feu est rouge. Que faites-vous ?",a:["Je m'arrête avant la ligne d'arrêt ou, à défaut, avant le feu","Je passe prudemment si personne ne vient","Je ralentis et je passe au pas"],r:0,g:1,e:"Feu rouge : interdiction de franchir la ligne d'arrêt ou, à défaut, le feu. Griller un feu rouge est une infraction grave."},
{t:"feux",i:{l:"orange"},q:"Le feu passe à l'orange fixe. Vous pouvez encore vous arrêter sans danger. Que faites-vous ?",a:["Je m'arrête","J'accélère pour passer avant le rouge","Je continue : l'orange signifie seulement prudence"],r:0,g:1,e:"Orange fixe : arrêt obligatoire, sauf si vous êtes si près du feu que vous ne pourriez plus vous arrêter en sécurité."},
{t:"feux",i:{l:"orange"},q:"Le feu passe à l'orange fixe alors que vous êtes tout près et ne pourriez plus vous arrêter en sécurité. Que faites-vous ?",a:["Je continue prudemment","Je freine brutalement","Je fais marche arrière"],r:0,e:"Si l'arrêt n'est plus possible dans des conditions de sécurité suffisantes, vous pouvez franchir le feu orange prudemment."},
{t:"feux",i:{l:"blink"},q:"Ce feu orange clignote. Qu'est-ce que cela signifie ?",a:["Passage permis avec prudence : les panneaux et les règles de priorité s'appliquent","Arrêt obligatoire","Le carrefour est fermé"],r:0,e:"L'orange clignotant impose une prudence accrue. La priorité est réglée par les panneaux du carrefour ou, à défaut, par la priorité de droite."},
{t:"feux",i:{l:"green"},q:"Le feu est vert, mais le carrefour est encombré et vous risquez d'y rester bloqué. Que faites-vous ?",a:["J'attends avant le carrefour","Je m'engage : j'ai le feu vert","Je klaxonne pour faire avancer la file"],r:0,e:"Même au vert, il est interdit de s'engager dans un carrefour si l'on risque d'y être immobilisé et de bloquer la circulation transversale."},
{t:"feux",i:{l:"green"},q:"Le feu est vert et vous tournez à droite. Des piétons traversent la rue dans laquelle vous entrez. Que faites-vous ?",a:["Je leur cède le passage","Je passe : j'ai le feu vert","Je klaxonne pour qu'ils se dépêchent"],r:0,g:1,e:"En changeant de direction, vous cédez le passage aux piétons qui traversent la voie dans laquelle vous entrez, et aux cyclistes qui continuent tout droit."},
{t:"feux",i:{l:"arrow"},q:"Que signifie ce feu vert en forme de flèche ?",a:["Vous pouvez circuler dans la direction indiquée par la flèche","Cette direction est interdite","Le feu va passer au rouge"],r:0,e:"Une flèche verte autorise uniquement la direction qu'elle indique."},
{t:"feux",i:{l:"red"},q:"Le feu est rouge. Vous voulez tourner à droite et rien n'arrive. Pouvez-vous passer ?",a:["Non","Oui, tourner à droite est toujours permis"],r:0,g:1,e:"Le rouge interdit aussi de tourner à droite, sauf si un feu vert en forme de flèche l'autorise. Certains carrefours permettent aux cyclistes de passer grâce à un panneau spécifique, mais pas aux voitures."},
{t:"feux",i:{l:"pn"},q:"À un passage à niveau, ces deux feux rouges clignotent alternativement. Que faites-vous ?",a:["Je m'arrête : il est interdit de passer","Je passe vite avant l'arrivée du train","Je passe si les barrières sont encore levées"],r:0,g:1,e:"Feux rouges clignotants alternatifs : interdiction absolue de franchir. Un train approche, même si les barrières ne sont pas encore baissées."},
{t:"feux",q:"Les barrières d'un passage à niveau commencent à se baisser. Que faites-vous ?",a:["Je m'arrête et je ne m'engage pas","J'accélère pour passer avant la fermeture","Je contourne les barrières si le train est encore loin"],r:0,g:1,e:"Il est interdit de s'engager sur un passage à niveau dès que les barrières se ferment ou que les feux rouges clignotent."},
{t:"feux",q:"Votre voiture tombe en panne sur un passage à niveau. Quelle est la priorité absolue ?",a:["Faire sortir tout le monde, s'éloigner des voies, puis prévenir les secours","Essayer de redémarrer jusqu'à ce que ça marche","Placer le triangle de danger"],r:0,e:"La vie des occupants passe d'abord : évacuez immédiatement et éloignez-vous des voies, puis appelez le 112 ou le numéro affiché au passage à niveau."},
{t:"feux",i:{ag:"up"},q:"Un agent qualifié lève le bras verticalement. Qu'est-ce que cela signifie ?",a:["Arrêt pour tous, sauf pour ceux qui ne peuvent plus s'arrêter en sécurité","Passage permis pour tous","Seuls les piétons doivent s'arrêter"],r:0,e:"Bras levé verticalement : arrêt pour tous les usagers, comme un feu orange. Ceux qui sont déjà trop près pour s'arrêter en sécurité peuvent continuer."},
{t:"feux",i:{ag:"side"},q:"Vous arrivez face à cet agent, qui tend les bras horizontalement. Que faites-vous ?",a:["Je m'arrête","Je passe","Je tourne à droite uniquement"],r:0,g:1,e:"Bras tendus horizontalement : arrêt pour les usagers qui arrivent face à l'agent ou dans son dos. Ceux qui arrivent dans l'axe des bras peuvent passer."},
{t:"feux",i:{ag:"side"},q:"Vous arrivez sur le côté de cet agent, dans l'axe de ses bras tendus. Que faites-vous ?",a:["Je peux passer, prudemment","Je dois m'arrêter","Je dois faire demi-tour"],r:0,e:"Les usagers qui arrivent dans la direction indiquée par les bras tendus peuvent passer. Ceux qui viennent de face ou de dos doivent s'arrêter."},
{t:"feux",q:"Le feu est rouge, mais un agent qualifié vous fait signe de passer. Que faites-vous ?",a:["Je passe : les injonctions de l'agent priment sur les feux","J'attends que le feu passe au vert","Je klaxonne pour signaler le problème"],r:0,e:"Ordre de priorité : agent qualifié, puis feux, puis panneaux, puis règles générales de circulation."},
{t:"feux",q:"Dans quel ordre les indications s'imposent-elles ?",a:["Agent qualifié, feux, panneaux, règles générales","Panneaux, feux, agent qualifié, règles générales","Règles générales, panneaux, feux, agent qualifié"],r:0,e:"Les injonctions d'un agent qualifié priment sur tout. Viennent ensuite les feux, puis les panneaux et enfin les règles de priorité générales."},
{t:"feux",q:"Un carrefour comporte un feu en service et un signal STOP. Le feu est vert. Que faites-vous ?",a:["Je suis le feu et je passe","Je m'arrête quand même au STOP","Je cède le passage à droite"],r:0,e:"Quand les feux fonctionnent, ils priment sur les panneaux de priorité. Si les feux sont éteints ou à l'orange clignotant, c'est le panneau qui compte."},
{t:"feux",q:"Les feux d'un carrefour sont éteints et aucun agent n'est présent. Qu'est-ce qui règle la priorité ?",a:["Les panneaux de priorité, ou à défaut la priorité de droite","Personne : le plus rapide passe","La plus grande route est toujours prioritaire"],r:0,e:"Sans feux en service, ce sont les signaux de priorité (B1, B5, B9…) qui s'appliquent, et à défaut la priorité de droite."},
{t:"feux",q:"Des feux rouges clignotent à la sortie d'une caserne de pompiers. Que faites-vous ?",a:["Je m'arrête : il est interdit de passer","Je passe prudemment","Je klaxonne"],r:0,g:1,e:"Les feux rouges clignotants (passages à niveau, ponts mobiles, sorties de véhicules prioritaires) interdisent de passer."},

/* ===== Priorités ===== */
{t:"priorites",i:{x:{o:[{f:"E",t:"B"}]}},q:"Carrefour sans signalisation. Vous conduisez la voiture bleue et allez tout droit. Qui passe en premier ?",a:["La voiture B","Moi (voiture bleue)"],r:0,g:1,e:"Sans signal ni feu, la priorité de droite s'applique. B arrive de votre droite : vous lui cédez le passage."},
{t:"priorites",i:{x:{o:[{f:"W",t:"B"}]}},q:"Carrefour sans signalisation. Vous allez tout droit. Qui passe en premier ?",a:["Moi (voiture bleue)","La voiture B"],r:0,e:"B vient de votre gauche. Vous êtes à sa droite : c'est lui qui doit vous céder le passage. Restez prudent malgré tout."},
{t:"priorites",i:{x:{sg:{S:"B1"},o:[{f:"W",t:"B"}]}},q:"Vous avez ce signal à votre droite. Qui passe en premier ?",a:["La voiture B","Moi (voiture bleue)"],r:0,g:1,e:"Le signal B1 vous oblige à céder le passage à tous les usagers de la voie que vous abordez, qu'ils viennent de gauche ou de droite."},
{t:"priorites",i:{x:{sg:{S:"B9",E:"B1"},o:[{f:"E",t:"B"}]}},q:"Vous circulez sur une route prioritaire. Qui passe en premier ?",a:["Moi (voiture bleue)","La voiture B"],r:0,e:"Vous êtes sur une route prioritaire (B9) et B a un signal « céder le passage ». La priorité de droite ne s'applique pas."},
{t:"priorites",i:{x:{sg:{S:"B17"},o:[{f:"E",t:"B"}]}},q:"Qui passe en premier ?",a:["La voiture B","Moi (voiture bleue)"],r:0,g:1,e:"B17 annonce un carrefour à priorité de droite. B vient de votre droite."},
{t:"priorites",i:{x:{sg:{S:"B15"},o:[{f:"E",t:"B"}]}},q:"Vous venez de passer ce signal. Qui passe en premier au carrefour ?",a:["Moi (voiture bleue)","La voiture B"],r:0,e:"B15 vous donne la priorité au prochain carrefour : B doit vous céder le passage, même s'il vient de droite."},
{t:"priorites",i:{x:{sg:{S:"B5"}}},q:"Aucun véhicule n'arrive. Que faites-vous ?",a:["Je marque l'arrêt complet à la ligne, puis je repars","Je ralentis fortement et je passe","Je passe : la voie est libre"],r:0,g:1,e:"Au STOP, l'arrêt complet est toujours obligatoire, même si la voie est libre."},
{t:"priorites",i:{x:{o:[{f:"W",k:"tram",t:"T"}]}},q:"Carrefour sans signalisation. Un tram arrive de votre gauche. Qui passe en premier ?",a:["Le tram","Moi (voiture bleue)"],r:0,g:1,e:"Vous devez céder le passage aux trams, même s'ils viennent de gauche, sauf signalisation contraire."},
{t:"priorites",i:{x:{md:"l",o:[{f:"N",t:"B"}]}},q:"Vous tournez à gauche. La voiture B arrive en face et continue tout droit. Qui passe en premier ?",a:["La voiture B","Moi (voiture bleue)"],r:0,g:1,e:"Le conducteur qui tourne à gauche doit céder le passage aux conducteurs qui arrivent en sens inverse."},
{t:"priorites",i:{x:{md:"l",o:[{f:"N",d:"r",t:"B"}]}},q:"Vous tournez à gauche. La voiture B, en face, tourne à sa droite. Qui passe en premier ?",a:["La voiture B","Moi (voiture bleue)"],r:0,e:"Vous tournez à gauche : vous cédez le passage au conducteur qui vient en sens inverse, même s'il tourne."},
{t:"priorites",i:{x:{o:[{f:"E",t:"B"},{f:"W",t:"C"}]}},q:"Carrefour sans signalisation, tout le monde va tout droit. Dans quel ordre passe-t-on ?",a:["B, puis moi, puis C","Moi, puis B, puis C","C, puis moi, puis B"],r:0,e:"Chacun cède à sa droite. B n'a personne à sa droite : il passe en premier. Vous suivez (B était à votre droite), puis C, qui devait vous céder le passage."},
{t:"priorites",i:{x:{md:"r",o:[{f:"S",k:"bike"}]}},q:"Vous tournez à droite. Un cycliste roule tout droit sur la piste cyclable à votre droite. Que faites-vous ?",a:["Je lui cède le passage","Je passe avant lui","Je klaxonne pour le prévenir"],r:0,g:1,e:"Celui qui change de direction cède le passage aux cyclistes qui continuent tout droit sur la piste cyclable. Contrôlez votre angle mort."},
{t:"priorites",i:{x:{sg:{S:"B9",W:"B5"},o:[{f:"W",t:"B"}]}},q:"Qui passe en premier ?",a:["Moi (voiture bleue)","La voiture B"],r:0,e:"Vous êtes sur une route prioritaire et B a un STOP : il doit s'arrêter et vous céder le passage."},
{t:"priorites",q:"Vous sortez d'un parking pour vous engager sur la chaussée. À qui devez-vous céder le passage ?",a:["À tous les usagers qui circulent sur la voie publique","Seulement aux véhicules venant de droite","À personne si la rue est calme"],r:0,g:1,e:"Le conducteur qui quitte un parking, une propriété ou un chemin de terre doit céder le passage à tous les autres usagers."},
{t:"priorites",q:"Vous débouchez d'un chemin de terre sur une route asphaltée. Une voiture arrive de votre gauche. Que faites-vous ?",a:["Je lui cède le passage","Je passe : elle vient de ma gauche"],r:0,g:1,e:"La priorité de droite ne joue pas quand vous sortez d'un chemin de terre : vous cédez le passage à tous."},
{t:"priorites",q:"Vous effectuez une manœuvre (marche arrière, demi-tour, sortie de stationnement). Qui a la priorité ?",a:["Les autres usagers","Moi, puisque j'ai mis mon clignotant","Seulement ceux qui viennent de droite"],r:0,e:"Le conducteur qui effectue une manœuvre doit céder le passage à tous les autres usagers."},
{t:"priorites",q:"Vous voulez passer sur la bande de gauche. Qui a la priorité ?",a:["Les véhicules qui circulent déjà sur cette bande","Moi, si j'ai mis mon clignotant","Le véhicule le plus rapide"],r:0,g:1,e:"Changer de bande est une manœuvre : vous cédez le passage à ceux qui y circulent déjà. Clignotant, rétroviseurs, angle mort."},
{t:"priorites",i:{s:"D5"},q:"Vous arrivez à un rond-point signalé par ce panneau. Qui a la priorité ?",a:["Les conducteurs qui circulent déjà sur le rond-point","Ceux qui entrent, puisqu'ils viennent de droite","Le véhicule le plus gros"],r:0,g:1,e:"Au carrefour giratoire (D5), vous cédez le passage aux usagers qui circulent déjà sur l'anneau."},
{t:"priorites",q:"Dans un rond-point, quand devez-vous mettre votre clignotant droit ?",a:["Avant de prendre la sortie","En entrant dans le rond-point","Jamais dans un rond-point"],r:0,e:"Annoncez votre sortie avec le clignotant droit juste avant de quitter le rond-point."},
{t:"priorites",q:"Un véhicule de secours arrive derrière vous avec feux bleus clignotants et sirène. Que faites-vous ?",a:["Je lui libère le passage, au besoin en m'arrêtant","Je continue normalement","J'accélère pour rester devant lui"],r:0,g:1,e:"Vous devez libérer le passage aux véhicules prioritaires qui utilisent ensemble le feu bleu clignotant et l'avertisseur sonore spécial. Dégagez en sécurité."},
{t:"priorites",q:"Une ambulance circule avec ses feux bleus allumés, mais sans sirène. Est-elle prioritaire ?",a:["Non, mais je reste prudent","Oui, exactement comme avec la sirène"],r:0,e:"Un véhicule prioritaire bénéficie de la priorité quand il utilise à la fois le feu bleu clignotant et l'avertisseur sonore spécial. Les feux bleus seuls signalent un danger : soyez prudent."},
{t:"priorites",q:"À un carrefour sans signalisation, un cycliste arrive de votre droite. Qui passe en premier ?",a:["Le cycliste","Moi, car je suis plus rapide"],r:0,g:1,e:"La priorité de droite s'applique à tous les conducteurs, cyclistes compris."},
{t:"priorites",q:"Une bande de circulation se termine (rétrécissement). Comment devez-vous vous insérer ?",a:["Rouler jusqu'au rétrécissement, puis s'insérer en alternance, un véhicule de chaque bande","S'insérer le plus tôt possible, quitte à freiner fort","Sur la bande qui continue, on ne laisse passer personne"],r:0,e:"C'est la « tirette » : on utilise les deux bandes jusqu'au rétrécissement, puis on s'insère en alternance."},
{t:"priorites",q:"Vous tournez à gauche dans une rue. Des piétons traversent cette rue. Que faites-vous ?",a:["Je leur cède le passage","Je passe avant eux","Je klaxonne pour qu'ils s'écartent"],r:0,g:1,e:"En changeant de direction, vous cédez le passage aux piétons qui traversent la voie dans laquelle vous entrez."},

/* ===== Vitesse ===== */
{t:"vitesse",q:"En Wallonie et en Flandre, en agglomération, sans signal particulier, la vitesse maximale est de…",a:["30 km/h","50 km/h","70 km/h"],r:1,e:"En agglomération, la règle générale est 50 km/h. De nombreuses zones 30 existent, et la Région de Bruxelles-Capitale applique 30 km/h par défaut."},
{t:"vitesse",q:"Dans la Région de Bruxelles-Capitale, en agglomération, la vitesse maximale par défaut est de…",a:["30 km/h","50 km/h","70 km/h"],r:0,e:"Depuis 2021, Bruxelles applique 30 km/h par défaut. Les grands axes peuvent être signalés à 50 ou 70 km/h."},
{t:"vitesse",q:"En Wallonie, hors agglomération, sur une route ordinaire sans signal, la vitesse maximale est de…",a:["70 km/h","90 km/h","120 km/h"],r:1,e:"En Wallonie, la vitesse maximale hors agglomération est de 90 km/h, sauf signalisation."},
{t:"vitesse",q:"En Flandre, hors agglomération, sur une route ordinaire sans signal, la vitesse maximale est de…",a:["70 km/h","90 km/h","120 km/h"],r:0,e:"Depuis 2017, la Flandre applique 70 km/h hors agglomération, sauf signalisation."},
{t:"vitesse",q:"Sur autoroute, quelle est la vitesse maximale pour une voiture ?",a:["100 km/h","120 km/h","130 km/h"],r:1,e:"120 km/h sur autoroute, sauf signalisation plus basse (travaux, météo, signalisation dynamique…)."},
{t:"vitesse",q:"Sur autoroute, quelle est la vitesse minimale, sauf circonstances ou signalisation ?",a:["50 km/h","70 km/h","90 km/h"],r:1,e:"Sur autoroute, il faut pouvoir rouler à au moins 70 km/h. Rouler plus lentement sans raison est dangereux."},
{t:"vitesse",q:"Dans une zone résidentielle (zone de rencontre), la vitesse maximale est de…",a:["20 km/h","30 km/h","50 km/h"],r:0,e:"20 km/h : les piétons peuvent y utiliser toute la largeur de la voie publique."},
{t:"vitesse",q:"Dans une zone piétonne, les véhicules autorisés doivent rouler…",a:["Au pas","À 20 km/h maximum","À 30 km/h maximum"],r:0,e:"Dans une zone piétonne, les rares véhicules autorisés circulent au pas et cèdent le passage aux piétons."},
{t:"vitesse",q:"Dans une rue cyclable, la vitesse maximale est de…",a:["20 km/h","30 km/h","50 km/h"],r:1,e:"Dans une rue cyclable, les véhicules à moteur ne peuvent pas dépasser 30 km/h ni dépasser les cyclistes."},
{t:"vitesse",i:{s:"Z30"},q:"Ce signal est placé aux abords d'une école. Quelle est la vitesse maximale ?",a:["30 km/h","40 km/h","50 km/h"],r:0,e:"Les abords d'écoles sont en général aménagés en zone 30. Soyez attentif aux enfants, dont le comportement est imprévisible."},
{t:"vitesse",q:"Si vous doublez votre vitesse, votre distance de freinage est multipliée par…",a:["2","3","4"],r:2,e:"La distance de freinage augmente avec le carré de la vitesse : deux fois plus vite, c'est quatre fois plus de distance pour freiner."},
{t:"vitesse",q:"À 90 km/h, quelle distance parcourez-vous pendant 1 seconde de réaction ?",a:["10 m","25 m","50 m"],r:1,e:"90 km/h = 25 m par seconde. Pendant votre temps de réaction, la voiture continue à pleine vitesse avant même que vous freiniez."},
{t:"vitesse",q:"La distance d'arrêt est égale à…",a:["La distance de réaction plus la distance de freinage","La distance de freinage seule","La distance avec le véhicule qui précède"],r:0,e:"Distance d'arrêt = distance parcourue pendant le temps de réaction + distance de freinage."},
{t:"vitesse",q:"Sur une route mouillée, la distance de freinage…",a:["Augmente fortement","Reste la même","Diminue"],r:0,e:"Sur route mouillée, l'adhérence diminue et la distance de freinage peut presque doubler. Ralentissez et augmentez vos distances."},
{t:"vitesse",q:"Quelle distance minimale garder avec le véhicule qui précède, par temps sec ?",a:["Au moins 2 secondes","1 seconde suffit","5 mètres, quelle que soit la vitesse"],r:0,e:"Règle des 2 secondes : comptez au moins 2 secondes entre le passage du véhicule qui vous précède et le vôtre devant un même repère. Davantage par mauvais temps."},
{t:"vitesse",q:"Vous roulez à la vitesse maximale autorisée, mais il y a du brouillard. Que faites-vous ?",a:["Je ralentis : je dois toujours adapter ma vitesse aux circonstances","Je garde ma vitesse, elle est autorisée","J'accélère pour sortir plus vite du brouillard"],r:0,g:1,e:"La vitesse maximale n'est pas une vitesse imposée. Vous devez toujours pouvoir vous arrêter devant un obstacle prévisible, dans la portion de route que vous voyez."},
{t:"vitesse",q:"Vous devez toujours pouvoir vous arrêter…",a:["Devant un obstacle prévisible, dans la distance que vous voyez libre devant vous","En moins de 10 mètres","Uniquement en agglomération"],r:0,e:"C'est la règle de base : adaptez votre vitesse à votre visibilité et aux conditions."},
{t:"vitesse",q:"Que devient votre champ de vision quand votre vitesse augmente ?",a:["Il se rétrécit","Il s'élargit","Il ne change pas"],r:0,e:"Plus vous allez vite, plus votre regard se porte loin et plus votre champ de vision se rétrécit : vous voyez moins ce qui arrive sur les côtés."},
{t:"vitesse",q:"Votre voiture glisse sur une nappe d'eau (aquaplaning). Que faites-vous ?",a:["Je lève le pied de l'accélérateur et je tiens le volant droit, sans freiner brusquement","Je freine à fond","Je donne un coup de volant"],r:0,e:"Lâchez l'accélérateur, gardez les roues droites et attendez que les pneus retrouvent l'adhérence. Un freinage brusque ou un coup de volant aggrave la perte de contrôle."},
{t:"vitesse",q:"Sur une route où la circulation est fluide, vous roulez anormalement lentement sans raison. Est-ce permis ?",a:["Non, il ne faut pas gêner la marche normale des autres usagers","Oui, rouler lentement est toujours plus sûr"],r:0,e:"Rouler à une vitesse anormalement réduite sans raison valable gêne les autres et peut provoquer des dépassements dangereux."},

/* ===== Dépassement ===== */
{t:"depassement",q:"En règle générale, de quel côté dépasse-t-on ?",a:["Par la gauche","Par la droite","Du côté où il y a le plus de place"],r:0,e:"On dépasse par la gauche. Il existe des exceptions précises (véhicule qui tourne à gauche, tram…)."},
{t:"depassement",q:"Dans quel cas devez-vous dépasser par la droite ?",a:["Quand le véhicule devant a signalé qu'il tourne à gauche et s'est placé à gauche","Sur autoroute, quand la bande de droite est libre","Quand le conducteur devant roule trop lentement"],r:0,e:"Un véhicule qui s'est placé à gauche pour tourner à gauche se dépasse par la droite. Sur autoroute, dépasser par la droite est interdit."},
{t:"depassement",q:"Un tram circule au milieu de la chaussée. Comment le dépasser ?",a:["Par la droite, s'il y a assez de place","Toujours par la gauche","Il est interdit de dépasser un tram"],r:0,e:"Les trams se dépassent normalement par la droite, si l'espace est suffisant."},
{t:"depassement",q:"Avant de dépasser, que devez-vous vérifier ?",a:["Que la voie est libre assez loin, que personne ne me dépasse et que je pourrai me rabattre sans gêner","Seulement que le véhicule devant roule lentement","Seulement que mon clignotant fonctionne"],r:0,e:"Un dépassement se prépare : visibilité, rétroviseurs, angle mort, clignotant, et assez de place pour se rabattre en sécurité."},
{t:"depassement",q:"Pouvez-vous dépasser une voiture dans un virage ou au sommet d'une côte, sans visibilité suffisante ?",a:["Non","Oui, si je vais vite"],r:0,g:1,e:"Dépasser sans visibilité suffisante (sommet de côte, virage) est une des infractions les plus graves : vous risquez un choc frontal."},
{t:"depassement",q:"Une voiture est en train de vous dépasser. Que devez-vous faire ?",a:["Serrer à droite et ne pas accélérer","Accélérer pour ne pas être dépassé","Me décaler vers le milieu de la chaussée"],r:0,e:"Le conducteur dépassé serre à droite et n'augmente pas sa vitesse."},
{t:"depassement",q:"En agglomération, quelle distance latérale minimale devez-vous laisser en dépassant un cycliste ?",a:["0,5 m","1 m","2 m"],r:1,e:"Au moins 1 m en agglomération, et 1,5 m hors agglomération. Si c'est impossible, restez derrière le cycliste."},
{t:"depassement",q:"Hors agglomération, quelle distance latérale minimale devez-vous laisser en dépassant un cycliste ?",a:["1 m","1,5 m","3 m"],r:1,e:"Hors agglomération, 1,5 m au minimum (1 m en agglomération)."},
{t:"depassement",q:"Vous voulez dépasser un cycliste, mais la place manque pour respecter la distance latérale. Que faites-vous ?",a:["Je reste derrière lui jusqu'à pouvoir dépasser correctement","Je le dépasse de près en klaxonnant","Je le dépasse en roulant sur le trottoir"],r:0,g:1,e:"Si la distance latérale ne peut pas être respectée, il faut patienter derrière le cycliste."},
{t:"depassement",q:"Dans une rue cyclable, pouvez-vous dépasser un cycliste ?",a:["Non","Oui, s'il roule lentement"],r:0,g:1,e:"Dans une rue cyclable, les véhicules à moteur ne peuvent pas dépasser les cyclistes, et la vitesse est limitée à 30 km/h."},
{t:"depassement",q:"Le véhicule devant vous s'arrête juste avant un passage pour piétons. Que faites-vous ?",a:["Je m'arrête aussi : un piéton traverse peut-être","Je le dépasse prudemment","Je le dépasse en klaxonnant"],r:0,g:1,e:"Un véhicule arrêté peut masquer un piéton qui traverse. Ne le dépassez pas : arrêtez-vous et cédez le passage aux piétons."},
{t:"depassement",q:"Pouvez-vous dépasser une voiture à l'approche d'un passage à niveau sans barrières ?",a:["Non","Oui, si aucun train n'est visible"],r:0,g:1,e:"Le dépassement est interdit à l'approche et sur un passage à niveau sans barrières."},
{t:"depassement",q:"Vous roulez sur une route prioritaire (B9) à l'approche d'un carrefour. Pouvez-vous dépasser ?",a:["Oui, si rien d'autre ne l'interdit et que c'est sans danger","Non, il est toujours interdit de dépasser à un carrefour"],r:0,e:"Le dépassement est en principe interdit à l'approche des carrefours, sauf notamment sur une route prioritaire ou quand le carrefour est réglé par des feux ou un agent."},
{t:"depassement",q:"Comment devez-vous signaler un dépassement ?",a:["Clignotant à gauche avant de déboîter, puis clignotant à droite avant de me rabattre","Par un appel de phares uniquement","Je n'ai pas besoin de le signaler"],r:0,e:"Annoncez toujours vos changements de direction et de bande, et faites-le à temps."},
{t:"depassement",q:"Sur une route étroite, un obstacle se trouve de votre côté et un véhicule arrive en face. Qui passe en premier ?",a:["Le véhicule qui arrive en face","Moi, j'étais là le premier","Le plus rapide"],r:0,e:"Quand le croisement est difficile à cause d'un obstacle, le conducteur du côté de l'obstacle cède le passage."},
{t:"depassement",q:"Vous croisez un véhicule sur une route étroite. Que faites-vous ?",a:["Je serre à droite et, au besoin, je ralentis ou je m'arrête","Je reste au milieu pour montrer que j'ai la priorité","Je fais un appel de phares et je continue"],r:0,e:"Pour croiser, chacun serre à droite et laisse une distance latérale suffisante."},

/* ===== Arrêt et stationnement ===== */
{t:"stationnement",q:"Un véhicule est « à l'arrêt » lorsqu'il est immobilisé…",a:["Le temps nécessaire pour embarquer ou débarquer des personnes ou des choses","Pendant plus de deux minutes","Devant un feu rouge"],r:0,e:"L'arrêt dure le temps de faire monter ou descendre des personnes, ou de charger et décharger. Au-delà, c'est du stationnement. Devant un feu rouge, vous êtes simplement immobilisé par la circulation."},
{t:"stationnement",q:"Un véhicule est « en stationnement » lorsqu'il est immobilisé…",a:["Au-delà du temps nécessaire pour embarquer ou débarquer des personnes ou des choses","Moteur coupé, même pour 10 secondes","Uniquement sur un parking payant"],r:0,e:"Le stationnement commence dès que l'immobilisation dépasse le temps nécessaire au chargement ou à l'embarquement."},
{t:"stationnement",q:"Il est interdit de stationner sur la chaussée à moins de combien de mètres avant un passage pour piétons ?",a:["3 m","5 m","10 m"],r:1,e:"Arrêt et stationnement sont interdits sur le passage pour piétons et à moins de 5 m avant celui-ci : un véhicule garé masquerait les piétons."},
{t:"stationnement",q:"Il est interdit de stationner à moins de combien de mètres de part et d'autre d'un panneau d'arrêt de bus ?",a:["5 m","15 m","30 m"],r:1,e:"Laissez 15 m libres de chaque côté du panneau d'arrêt de bus ou de tram, pour que le véhicule puisse s'arrêter le long du trottoir."},
{t:"stationnement",q:"Le stationnement est interdit si la largeur de chaussée laissée libre devient inférieure à…",a:["2 m","3 m","5 m"],r:1,e:"Il faut laisser au moins 3 m de chaussée libre pour que les autres véhicules puissent passer."},
{t:"stationnement",q:"Il est interdit de stationner à moins de combien de mètres d'un carrefour (bord de la chaussée transversale) ?",a:["3 m","5 m","20 m"],r:1,e:"À moins de 5 m d'un carrefour, un véhicule garé gêne la visibilité et les manœuvres."},
{t:"stationnement",q:"Pouvez-vous stationner devant l'entrée d'un garage (accès carrossable) ?",a:["Non, sauf si le numéro de ma plaque est affiché lisiblement sur cette entrée","Oui, si je reste moins d'une heure","Oui, si le garage est fermé"],r:0,e:"Le stationnement devant un accès carrossable est interdit. Exception : le véhicule dont le numéro d'immatriculation est affiché sur l'entrée."},
{t:"stationnement",q:"Dans une rue à double sens, de quel côté devez-vous stationner ?",a:["À droite, par rapport à mon sens de circulation","Du côté où il y a de la place","À gauche, pour mieux voir les piétons"],r:0,e:"Dans une rue à double sens, on stationne à droite par rapport à son sens de marche."},
{t:"stationnement",q:"Dans une rue à sens unique, de quel côté pouvez-vous stationner ?",a:["Des deux côtés, sauf signalisation contraire","Uniquement à droite","Uniquement à gauche"],r:0,e:"Dans une rue à sens unique, le stationnement est permis à droite comme à gauche, sauf interdiction."},
{t:"stationnement",q:"En zone bleue, combien de temps pouvez-vous stationner avec le disque, sauf indication contraire ?",a:["1 heure","2 heures","4 heures"],r:1,e:"En zone bleue, la durée maximale est de 2 heures, sauf si la signalisation indique autre chose. Le disque doit être visible derrière le pare-brise."},
{t:"stationnement",q:"Vous arrivez à 10 h 10 en zone bleue. Sur quelle heure placez-vous la flèche du disque ?",a:["10 h 00","10 h 10","10 h 30"],r:2,e:"La flèche se place sur le trait qui suit l'heure d'arrivée, donc 10 h 30. Vous pouvez alors rester jusqu'à 12 h 30."},
{t:"stationnement",q:"Stationner sur un trottoir est…",a:["Interdit, sauf si une signalisation l'autorise","Permis si deux roues restent sur la chaussée","Permis la nuit"],r:0,e:"Les trottoirs sont réservés aux piétons. Le stationnement n'y est permis que si une signalisation l'autorise."},
{t:"stationnement",q:"Pouvez-vous vous arrêter quelques instants sur une piste cyclable pour déposer quelqu'un ?",a:["Non","Oui, si j'allume mes feux de détresse"],r:0,e:"L'arrêt et le stationnement sont interdits sur les pistes cyclables. Les feux de détresse ne rendent pas légal un arrêt interdit."},
{t:"stationnement",q:"Avant d'ouvrir votre portière côté rue, que devez-vous faire ?",a:["Vérifier qu'aucun usager n'arrive, en particulier un cycliste","Ouvrir vite pour gêner le moins longtemps possible","Rien : ceux qui arrivent doivent m'éviter"],r:0,g:1,e:"Ouvrir une portière sans regarder peut faucher un cycliste. Regardez dans le rétroviseur et par-dessus l'épaule. Astuce : ouvrez avec la main la plus éloignée de la portière."},
{t:"stationnement",q:"Stationner en double file est…",a:["Interdit","Permis pour moins de 5 minutes","Permis si les feux de détresse sont allumés"],r:0,e:"Le stationnement en double file est interdit."},
{t:"stationnement",q:"Hors agglomération, sur une route signalée comme prioritaire (B9), pouvez-vous stationner sur la chaussée ?",a:["Non","Oui"],r:0,e:"Hors agglomération, le stationnement est interdit sur la chaussée des routes prioritaires. Garez-vous en dehors de la chaussée."},
{t:"stationnement",q:"Qui peut utiliser une place de stationnement réservée aux personnes handicapées ?",a:["Uniquement les véhicules qui affichent la carte spéciale de stationnement","Tout le monde pour moins de 15 minutes","Les livreurs"],r:0,e:"Ces emplacements sont réservés aux véhicules qui transportent une personne handicapée et qui affichent la carte spéciale."},
{t:"stationnement",q:"Dans une zone résidentielle, où pouvez-vous stationner ?",a:["Uniquement aux emplacements délimités (marquage, revêtement différent ou signal P)","Partout, puisque la vitesse est faible","Sur les trottoirs"],r:0,e:"Dans une zone résidentielle ou de rencontre, le stationnement n'est permis qu'aux endroits aménagés et signalés."},
{t:"stationnement",q:"Vous quittez votre voiture garée. Que devez-vous faire ?",a:["Couper le moteur, serrer le frein de stationnement et retirer la clé","Laisser tourner le moteur si je reviens vite","Laisser la clé pour qu'on puisse la déplacer"],r:0,e:"Un véhicule laissé sans surveillance doit être immobilisé et protégé contre le vol."},
{t:"stationnement",q:"Pour vous garer, vous reculez dans une rue. Qu'est-ce qui est obligatoire ?",a:["Céder le passage aux autres usagers et contrôler tout autour du véhicule","Allumer les feux de détresse","Klaxonner avant de reculer"],r:0,e:"La marche arrière est une manœuvre : vous cédez le passage à tous et vous contrôlez rétroviseurs et angles morts."},

/* ===== Autoroute ===== */
{t:"autoroute",q:"Lequel de ces usagers n'a pas accès à l'autoroute ?",a:["Un cyclomoteur","Une moto de 125 cm³","Une camionnette"],r:0,e:"Les piétons, les cyclistes et les cyclomoteurs, notamment, sont interdits sur l'autoroute."},
{t:"autoroute",q:"Vous rejoignez l'autoroute par la bande d'accélération. Qui a la priorité ?",a:["Les véhicules qui circulent déjà sur l'autoroute","Moi, si j'ai mis mon clignotant","Moi, puisque je viens de droite"],r:0,g:1,e:"Vous adaptez votre vitesse sur la bande d'accélération et vous vous insérez en cédant le passage aux usagers de l'autoroute."},
{t:"autoroute",q:"Sur une autoroute à plusieurs bandes, sur quelle bande devez-vous rouler normalement ?",a:["La bande de droite ; les autres servent à dépasser","La bande du milieu","Celle que je préfère"],r:0,e:"Roulez à droite. Les bandes de gauche servent au dépassement. Rester sur la bande du milieu sans raison gêne les autres."},
{t:"autoroute",q:"Vous avez manqué votre sortie d'autoroute. Que faites-vous ?",a:["Je continue jusqu'à la sortie suivante","Je fais marche arrière sur la bande d'arrêt d'urgence","Je fais demi-tour par la berme centrale"],r:0,g:1,e:"Marche arrière, demi-tour et traversée de la berme centrale sont interdits sur autoroute."},
{t:"autoroute",q:"Quand pouvez-vous utiliser la bande d'arrêt d'urgence ?",a:["Uniquement en cas de nécessité (panne, malaise…)","Pour dépasser dans un embouteillage","Pour faire une courte pause"],r:0,g:1,e:"La bande d'arrêt d'urgence est réservée aux situations de nécessité. Rouler dessus pour remonter une file est interdit et dangereux."},
{t:"autoroute",q:"En cas de panne sur autoroute, à quelle distance minimale placez-vous le triangle de danger ?",a:["30 m","50 m","100 m"],r:2,e:"Sur autoroute, le triangle se place à au moins 100 m derrière le véhicule (30 m sur les autres routes)."},
{t:"autoroute",q:"Votre voiture est en panne sur la bande d'arrêt d'urgence. Où attendez-vous les secours ?",a:["Derrière la glissière de sécurité, hors de la chaussée","Dans la voiture, ceinture attachée","Debout à côté de la voiture"],r:0,g:1,e:"Gilet fluorescent, feux de détresse, sortie côté droit, puis tout le monde derrière la glissière. Rester dans le véhicule ou à côté expose au risque d'être percuté."},
{t:"autoroute",q:"Un bouchon se forme sur une autoroute à trois bandes. Vous êtes sur la bande de gauche. Que faites-vous ?",a:["Je serre à gauche pour former le couloir de secours","Je serre à droite","Je reste au milieu de ma bande"],r:0,e:"Couloir de secours : la bande de gauche serre à gauche, toutes les autres serrent à droite. On le forme dès que la file se forme."},
{t:"autoroute",q:"Un bouchon se forme sur une route à deux bandes dans votre sens. Vous êtes sur la bande de droite. Que faites-vous ?",a:["Je serre à droite","Je serre à gauche","Je passe sur la bande d'arrêt d'urgence"],r:0,e:"Sur deux bandes : la gauche serre à gauche, la droite serre à droite. Le couloir s'ouvre entre les deux."},
{t:"autoroute",q:"Quand devez-vous former le couloir de secours ?",a:["Dès qu'une file se forme, même si aucun véhicule de secours n'est visible","Seulement quand j'entends une sirène","Seulement sur ordre de la police"],r:0,e:"Le couloir de secours se forme dès le ralentissement, sur toute route d'au moins deux bandes dans le même sens, pour que les secours ne perdent pas de temps."},
{t:"autoroute",q:"Pouvez-vous vous arrêter sur l'autoroute pour régler votre GPS ?",a:["Non, l'arrêt et le stationnement n'y sont permis qu'aux endroits prévus","Oui, sur la bande d'arrêt d'urgence","Oui, si j'allume mes feux de détresse"],r:0,e:"Utilisez une aire de repos ou de stationnement. La bande d'arrêt d'urgence n'est pas un parking."},
{t:"autoroute",q:"Dans un tunnel, quels feux allumez-vous, même en journée ?",a:["Les feux de croisement","Aucun si le tunnel est éclairé","Le feu antibrouillard arrière"],r:0,e:"Allumez vos feux de croisement dans les tunnels, même éclairés : vous êtes mieux vu et vous voyez mieux."},
{t:"autoroute",q:"Dans un tunnel, qu'est-ce qui est interdit ?",a:["Faire demi-tour ou marche arrière","Garder une distance de sécurité","Rouler avec les feux de croisement"],r:0,e:"Demi-tour et marche arrière sont interdits dans les tunnels. Gardez vos distances : un incident y est particulièrement dangereux."},
{t:"autoroute",q:"Sur autoroute, pouvez-vous dépasser par la droite un véhicule qui traîne sur la bande de gauche ?",a:["Non","Oui, si la bande de droite est libre"],r:0,g:1,e:"Sur autoroute aussi, le dépassement se fait par la gauche. Patientez jusqu'à ce que le conducteur se rabatte."},

/* ===== Éclairage et signaux ===== */
{t:"eclairage",q:"Quand devez-vous allumer les feux de croisement ?",a:["La nuit, et quand on ne voit plus distinctement à environ 200 m","Uniquement sur autoroute","Uniquement quand il pleut"],r:0,e:"Feux de croisement : de la tombée de la nuit au lever du jour, et chaque fois que la visibilité tombe sous environ 200 m (pluie, brouillard, neige)."},
{t:"eclairage",q:"Le feu antibrouillard arrière ne peut être allumé que si la visibilité est inférieure à…",a:["50 m","100 m","200 m"],r:1,e:"Feu antibrouillard arrière : seulement par brouillard, neige ou forte pluie, quand la visibilité est inférieure à 100 m. Sinon il éblouit les conducteurs derrière vous."},
{t:"eclairage",q:"Quand pouvez-vous utiliser les feux antibrouillard avant ?",a:["Par brouillard, chute de neige ou forte pluie","La nuit en agglomération","Toujours, hors agglomération"],r:0,e:"Les feux antibrouillard avant sont réservés au brouillard, à la neige et aux fortes pluies."},
{t:"eclairage",q:"Vous roulez la nuit en feux de route. Quand devez-vous passer en feux de croisement ?",a:["Quand je croise un usager ou que je suis un véhicule de près","Uniquement en agglomération","Jamais hors agglomération"],r:0,g:1,e:"Les feux de route éblouissent. Passez en feux de croisement dès que vous croisez un usager ou suivez un autre véhicule à faible distance."},
{t:"eclairage",q:"La nuit, pouvez-vous rouler avec les seuls feux de position ?",a:["Non","Oui, en agglomération éclairée"],r:0,e:"Les feux de position seuls ne suffisent pas pour circuler : on vous voit mal et vous ne voyez pas la route."},
{t:"eclairage",q:"Il y a du brouillard en journée. Vos feux de jour automatiques suffisent-ils ?",a:["Non, j'allume les feux de croisement","Oui, ils éclairent comme des feux de croisement"],r:0,e:"Sur beaucoup de voitures, les feux de jour n'allument pas les feux arrière : on ne vous voit pas de derrière. Allumez les feux de croisement."},
{t:"eclairage",q:"Quand devez-vous allumer vos feux de détresse ?",a:["Quand mon véhicule immobilisé constitue un danger (panne, accident)","Pour stationner en double file","Quand il pleut fort"],r:0,e:"Les feux de détresse signalent un véhicule qui représente un danger. Ils ne permettent pas de s'arrêter là où c'est interdit."},
{t:"eclairage",q:"Vous êtes ébloui par les phares d'un véhicule qui arrive en face. Que faites-vous ?",a:["Je ralentis, je regarde le bord droit de la route et je m'arrête au besoin","Je lui réponds en feux de route","Je ferme les yeux un instant"],r:0,e:"Ne répondez pas par un éblouissement. Ralentissez et guidez-vous sur le bord droit de la chaussée."},
{t:"eclairage",q:"En agglomération, quand pouvez-vous utiliser l'avertisseur sonore (klaxon) ?",a:["Uniquement pour éviter un accident","Pour saluer quelqu'un","Pour demander qu'on libère le passage"],r:0,e:"En agglomération, le klaxon est réservé aux situations de danger immédiat."},
{t:"eclairage",q:"La nuit, comment avertir un conducteur que vous allez le dépasser ?",a:["Par de brefs appels de phares","Par un long coup de klaxon","En allumant les feux de détresse"],r:0,e:"La nuit, de brefs appels lumineux remplacent l'avertisseur sonore."},
{t:"eclairage",q:"Quand devez-vous mettre votre clignotant ?",a:["À temps, avant de changer de direction ou de bande, ou de démarrer","Seulement si d'autres véhicules sont présents","Pendant le changement de direction uniquement"],r:0,e:"Le clignotant s'actionne assez tôt pour que les autres comprennent votre intention, même si vous ne voyez personne."},
{t:"eclairage",q:"Avant de partir, votre pare-brise est givré. Que faites-vous ?",a:["Je dégage complètement toutes les vitres","Je gratte un petit hublot devant moi","Je pars et j'attends que le chauffage dégivre"],r:0,e:"Vous devez avoir une visibilité suffisante dans toutes les directions : dégivrez entièrement les vitres et les rétroviseurs."},
{t:"eclairage",q:"Il pleut fortement en journée et la visibilité baisse. Que faites-vous ?",a:["J'allume les feux de croisement et je ralentis","J'allume le feu antibrouillard arrière, quelle que soit la visibilité","Je n'allume rien, il fait jour"],r:0,e:"Par forte pluie, les feux de croisement vous rendent visible. Le feu antibrouillard arrière ne s'utilise que si la visibilité tombe sous 100 m."},

/* ===== Usagers ===== */
{t:"usagers",q:"Un piéton est engagé, ou s'apprête à s'engager, sur un passage pour piétons. Que faites-vous ?",a:["Je lui cède le passage","Je passe si j'arrive avant lui au milieu","Je klaxonne pour le prévenir"],r:0,g:1,e:"Aux passages pour piétons sans feux, approchez à allure modérée et cédez le passage aux piétons qui traversent ou vont traverser."},
{t:"usagers",q:"Un piéton traverse la chaussée à quelques mètres d'un passage pour piétons. Que faites-vous ?",a:["Je ralentis et je m'arrête si nécessaire pour éviter l'accident","Je garde ma vitesse : il n'est pas sur le passage","Je klaxonne longuement"],r:0,e:"Même si le piéton est en tort, vous devez tout faire pour éviter l'accident."},
{t:"usagers",q:"Une personne avec une canne blanche s'apprête à traverser. Que faites-vous ?",a:["Je redouble de prudence, je ralentis et je m'arrête si nécessaire","Je klaxonne pour la guider","Je passe vite avant qu'elle ne s'engage"],r:0,g:1,e:"La canne blanche signale une personne aveugle ou malvoyante. Elle ne vous voit pas : arrêtez-vous et laissez-la traverser."},
{t:"usagers",q:"Un ballon roule sur la chaussée devant vous. Que faites-vous ?",a:["Je freine : un enfant peut le suivre","Je l'évite et je continue","J'accélère pour passer avant"],r:0,e:"Un ballon annonce souvent un enfant qui court derrière."},
{t:"usagers",q:"Des enfants jouent au bord de la route. Que faites-vous ?",a:["Je ralentis et je reste prêt à freiner","Je klaxonne et je continue","Je garde ma vitesse, ils m'ont vu"],r:0,e:"Les enfants ont un comportement imprévisible et évaluent mal la vitesse des véhicules."},
{t:"usagers",q:"En agglomération, un bus à l'arrêt met son clignotant pour repartir. Que faites-vous ?",a:["Je ralentis et, au besoin, je m'arrête pour le laisser repartir","J'accélère pour le dépasser avant qu'il démarre","Je klaxonne pour garder la priorité"],r:0,e:"En agglomération, vous devez permettre aux bus de quitter leur arrêt quand ils signalent leur intention."},
{t:"usagers",q:"Un bus de transport scolaire est à l'arrêt, feux orange clignotants allumés. Que faites-vous ?",a:["Je ralentis fortement, prêt à m'arrêter : des enfants peuvent traverser","Je le dépasse à vitesse normale","Je klaxonne pour prévenir les enfants"],r:0,g:1,e:"Les feux orange clignotants signalent la montée ou la descente d'enfants. Soyez extrêmement prudent."},
{t:"usagers",q:"Un tram s'arrête à un arrêt sans refuge : les voyageurs montent et descendent par la chaussée. Que faites-vous ?",a:["Je m'arrête si nécessaire pour laisser passer les voyageurs","Je le dépasse à vitesse normale","Je klaxonne pour que les voyageurs se dépêchent"],r:0,g:1,e:"Les voyageurs traversent la chaussée pour monter ou descendre : laissez-les passer en toute sécurité."},
{t:"usagers",q:"Un enfant de 8 ans roule à vélo sur le trottoir. Est-ce permis ?",a:["Oui, les enfants de moins de 10 ans peuvent rouler sur le trottoir","Non, les vélos n'ont jamais accès au trottoir"],r:0,e:"Les cyclistes de moins de 10 ans peuvent rouler sur le trottoir, sans mettre les piétons en danger."},
{t:"usagers",q:"Dans une rue à sens unique limité, que pouvez-vous rencontrer ?",a:["Des cyclistes qui roulent en sens inverse","Des voitures qui roulent en sens inverse","Des bus uniquement"],r:0,e:"Un sens unique limité permet aux cyclistes (et parfois à d'autres usagers indiqués) de circuler dans les deux sens. Serrez à droite et croisez-les prudemment."},
{t:"usagers",q:"Dans une zone résidentielle (zone de rencontre), les piétons…",a:["Peuvent utiliser toute la largeur de la voie publique","Doivent rester sur le trottoir","N'ont aucune priorité"],r:0,e:"En zone résidentielle, les piétons peuvent utiliser toute la largeur de la voie. Vous roulez à 20 km/h maximum et ne devez pas les mettre en danger."},
{t:"usagers",q:"Hors agglomération, sur une route sans trottoir ni accotement praticable, de quel côté les piétons marchent-ils en principe ?",a:["À gauche, face aux véhicules","À droite, dans le sens des véhicules","Au milieu de la chaussée"],r:0,e:"Hors agglomération, les piétons marchent en principe sur le bord gauche, pour voir arriver les véhicules. Soyez attentif, surtout la nuit."},
{t:"usagers",q:"Vous allez dépasser un cavalier. Que faites-vous ?",a:["Je ralentis, je laisse beaucoup d'espace et j'évite tout bruit brusque","Je klaxonne pour qu'il se range","Je le frôle à vitesse normale"],r:0,e:"Un cheval peut s'effrayer. Ralentissez, écartez-vous largement et évitez le klaxon."},
{t:"usagers",q:"Avant de tourner à droite, pourquoi tourner la tête et regarder par-dessus l'épaule ?",a:["Pour contrôler l'angle mort, où peut se trouver un cycliste","C'est inutile si mes rétroviseurs sont bien réglés","Pour vérifier que mon clignotant fonctionne"],r:0,g:1,e:"Les rétroviseurs ne montrent pas tout : un cycliste ou un scooter peut se trouver dans l'angle mort."},
{t:"usagers",q:"Une personne âgée traverse lentement alors que votre feu passe au vert. Que faites-vous ?",a:["J'attends qu'elle ait fini de traverser","Je klaxonne pour qu'elle se dépêche","Je la contourne"],r:0,e:"Un piéton encore engagé sur la chaussée doit pouvoir terminer sa traversée en sécurité."},

/* ===== Marquages ===== */
{t:"marquages",i:{m:"continue"},q:"Pouvez-vous franchir cette ligne pour dépasser le camion ?",a:["Non","Oui, si personne n'arrive en face"],r:0,g:1,e:"Ligne blanche continue : interdiction de la franchir et de circuler dessus."},
{t:"marquages",i:{m:"discontinue"},q:"Pouvez-vous franchir cette ligne pour dépasser le camion ?",a:["Oui, si le dépassement est sans danger","Non, jamais"],r:0,e:"Une ligne discontinue peut être franchie, à condition que la manœuvre soit sans danger."},
{t:"marquages",i:{m:"mixte",side:"me"},q:"Vous conduisez la voiture bleue. Pouvez-vous franchir cette double ligne pour dépasser ?",a:["Oui : la ligne discontinue est de mon côté","Non : il y a une ligne continue"],r:0,e:"Ligne mixte : seule compte la ligne la plus proche de vous. Discontinue de votre côté : vous pouvez la franchir."},
{t:"marquages",i:{m:"mixte",side:"other"},q:"Vous conduisez la voiture bleue. Pouvez-vous franchir cette double ligne pour dépasser ?",a:["Non : la ligne continue est de mon côté","Oui : il y a une ligne discontinue"],r:0,g:1,e:"La ligne la plus proche de vous est continue : vous ne pouvez pas la franchir."},
{t:"marquages",i:{m:"dents"},q:"Que signifie ce marquage en travers de votre bande ?",a:["Céder le passage","Ralentisseur","Passage pour cyclistes"],r:0,e:"La ligne de triangles indique où vous arrêter, si nécessaire, pour céder le passage. Elle accompagne souvent le signal B1."},
{t:"marquages",i:{m:"arret"},q:"Que signifie cette large ligne blanche continue en travers de votre bande ?",a:["L'endroit où je dois m'arrêter (STOP ou feu)","Le début d'une zone 30","Une bande réservée aux bus"],r:0,e:"La ligne d'arrêt indique où s'arrêter à un STOP ou à un feu rouge."},
{t:"marquages",i:{m:"hachures"},q:"Que signifie cette zone hachurée ?",a:["Une zone d'évitement : je ne peux pas y circuler","Une zone de stationnement","Une bande de dépassement"],r:0,e:"Les zones d'évitement (hachures blanches délimitées) ne peuvent servir ni à circuler ni à stationner."},
{t:"marquages",i:{m:"jaune-disc"},q:"Une ligne jaune discontinue est tracée le long du bord de la chaussée. Qu'est-ce que cela signifie ?",a:["Stationnement interdit, l'arrêt reste permis","Arrêt et stationnement interdits","Stationnement réservé aux taxis"],r:0,e:"Ligne jaune discontinue : stationnement interdit. Ligne jaune continue : arrêt et stationnement interdits."},
{t:"marquages",i:{m:"jaune-cont"},q:"Une ligne jaune continue est tracée le long du bord de la chaussée. Qu'est-ce que cela signifie ?",a:["Arrêt et stationnement interdits","Stationnement interdit, l'arrêt reste permis","Stationnement payant"],r:0,e:"Ligne jaune continue : arrêt et stationnement interdits de ce côté."},
{t:"marquages",i:{m:"rabattement"},q:"Que vous annoncent ces flèches obliques sur la chaussée ?",a:["Une ligne continue arrive : rabattez-vous à droite","Une sortie d'autoroute","Une piste cyclable"],r:0,e:"Les flèches de rabattement annoncent une ligne continue : terminez votre dépassement et regagnez votre bande."},
{t:"marquages",q:"Avant un carrefour, des flèches de sélection sont peintes sur les bandes. Que devez-vous faire ?",a:["Choisir ma bande à temps et suivre la direction indiquée par sa flèche","Les ignorer s'il n'y a pas de trafic","Changer de bande au dernier moment si nécessaire"],r:0,e:"Une fois engagé sur une bande avec flèche de sélection, vous devez suivre la direction qu'elle indique."},
{t:"marquages",q:"Que signifient de larges bandes blanches parallèles à l'axe de la chaussée ?",a:["Un passage pour piétons","Une zone d'évitement","Un parking"],r:0,e:"Le passage pour piétons est formé de bandes blanches parallèles à l'axe de la chaussée."},

/* ===== Conducteur ===== */
{t:"conducteur",q:"Quel est le taux d'alcool maximal autorisé pour un conducteur non professionnel ?",a:["0,2 g/l de sang","0,5 g/l de sang","0,8 g/l de sang"],r:1,e:"0,5 g/l de sang, soit 0,22 mg/l d'air expiré. Pour les conducteurs professionnels, la limite est de 0,2 g/l."},
{t:"conducteur",q:"Quelle est la limite d'alcool pour un conducteur professionnel (bus, camion…) ?",a:["0,2 g/l de sang","0,5 g/l de sang","0,8 g/l de sang"],r:0,e:"Les conducteurs professionnels sont soumis à une limite plus stricte de 0,2 g/l."},
{t:"conducteur",q:"Comment faire baisser plus vite votre taux d'alcool ?",a:["C'est impossible : seul le temps l'élimine","Boire beaucoup de café","Prendre une douche froide"],r:0,e:"Le foie élimine l'alcool à un rythme lent et constant. Café, douche ou air frais n'y changent rien."},
{t:"conducteur",q:"Même à faible dose, quel est l'effet de l'alcool sur la conduite ?",a:["Il allonge le temps de réaction et réduit le champ visuel","Il améliore les réflexes","Il n'a d'effet qu'au-delà de la limite légale"],r:0,e:"Dès les premiers verres, l'alcool ralentit les réflexes, rétrécit le champ visuel et pousse à prendre des risques."},
{t:"conducteur",q:"Vous avez fumé du cannabis. Pouvez-vous conduire ?",a:["Non : conduire sous l'influence de drogue est interdit","Oui, si je me sens bien","Oui, si j'attends une heure"],r:0,g:1,e:"La conduite sous l'influence de drogues est interdite. Un test salivaire positif suffit à constater l'infraction."},
{t:"conducteur",q:"Votre médecin vous a prescrit un médicament. Que faites-vous avant de conduire ?",a:["Je lis la notice et je demande conseil : certains médicaments rendent somnolent","Rien : un médicament prescrit est sans danger","Je double la dose pour être en forme"],r:0,e:"Certains médicaments diminuent la vigilance. Vérifiez la notice et demandez l'avis de votre médecin ou de votre pharmacien."},
{t:"conducteur",q:"Sur un long trajet, toutes les combien de temps faut-il faire une pause ?",a:["Toutes les 2 heures environ","Toutes les 5 heures","Seulement quand on a faim"],r:0,e:"Une pause toutes les 2 heures environ limite la fatigue, qui s'accumule sans qu'on s'en rende compte."},
{t:"conducteur",q:"Vous bâillez et vos paupières deviennent lourdes au volant. Que faites-vous ?",a:["Je m'arrête dans un endroit sûr et je me repose","J'ouvre la fenêtre et je monte le son de la radio","J'accélère pour arriver plus vite"],r:0,e:"Ce sont des signes de somnolence. Seul le repos est efficace : une courte sieste de 15 à 20 minutes peut aider."},
{t:"conducteur",q:"Pouvez-vous utiliser votre téléphone tenu en main pendant que vous conduisez ?",a:["Non","Oui, pour un appel court","Oui, à faible vitesse"],r:0,g:1,e:"Tenir son téléphone en main en conduisant est interdit, même pour un appel court. Un kit mains libres est permis, mais il distrait aussi."},
{t:"conducteur",q:"Vous êtes arrêté à un feu rouge. Pouvez-vous écrire un message sur votre téléphone tenu en main ?",a:["Non","Oui, puisque le véhicule est immobilisé"],r:0,g:1,e:"À un feu rouge ou dans un bouchon, vous êtes toujours en train de conduire : le téléphone en main reste interdit."},
{t:"conducteur",q:"Qui doit porter la ceinture de sécurité ?",a:["Le conducteur et tous les passagers, à l'avant comme à l'arrière","Le conducteur et le passager avant seulement","Personne en agglomération"],r:0,e:"La ceinture est obligatoire pour tous les occupants, à toutes les places qui en sont équipées."},
{t:"conducteur",q:"Jusqu'à quelle taille un enfant doit-il être attaché dans un dispositif de retenue adapté (siège enfant, rehausseur) ?",a:["1,20 m","1,35 m","1,50 m"],r:1,e:"Les enfants de moins de 1,35 m doivent utiliser un dispositif de retenue adapté à leur taille et à leur poids."},
{t:"conducteur",q:"Vous installez un siège enfant dos à la route sur le siège passager avant. Que devez-vous faire ?",a:["Désactiver l'airbag passager","Rien de particulier","Reculer le siège au maximum, l'airbag peut rester actif"],r:0,g:1,e:"Un airbag frontal actif face à un siège dos à la route peut tuer l'enfant en cas de choc."},
{t:"conducteur",q:"Comment régler correctement l'appuie-tête ?",a:["Le haut de l'appuie-tête au niveau du sommet de la tête","Au niveau de la nuque","Le plus bas possible"],r:0,e:"Bien réglé, l'appuie-tête protège la nuque en cas de choc arrière (coup du lapin)."},
{t:"conducteur",q:"Qu'est-ce que l'angle mort ?",a:["Une zone autour du véhicule que les rétroviseurs ne montrent pas","Un virage sans visibilité","Le dernier mètre devant le pare-chocs"],r:0,e:"Avant de changer de bande ou de tourner, tournez la tête pour contrôler l'angle mort."},
{t:"conducteur",q:"Vous êtes énervé après une dispute. Quel est le risque au volant ?",a:["Être moins attentif et prendre plus de risques","Aucun, la colère aide à se concentrer","Conduire forcément plus prudemment"],r:0,e:"Les émotions fortes réduisent l'attention et poussent à une conduite agressive. Prenez le temps de vous calmer avant de partir."},

/* ===== Véhicule et accident ===== */
{t:"vehicule",q:"Quels équipements sont obligatoires dans une voiture en Belgique ?",a:["Triangle de danger, gilet fluorescent, trousse de secours et extincteur","Triangle et gilet seulement","Aucun équipement n'est obligatoire"],r:0,e:"Ces quatre équipements doivent se trouver dans le véhicule."},
{t:"vehicule",q:"Hors autoroute, à quelle distance minimale placez-vous le triangle de danger derrière un véhicule en panne ?",a:["10 m","30 m","100 m"],r:1,e:"30 m au moins sur les routes ordinaires, 100 m au moins sur autoroute."},
{t:"vehicule",q:"Avant de sortir de la voiture pour placer le triangle, que faites-vous ?",a:["J'enfile mon gilet fluorescent","Rien, je me dépêche","J'éteins tous les feux"],r:0,e:"Le gilet vous rend visible pour les autres conducteurs. Allumez aussi les feux de détresse."},
{t:"vehicule",q:"Quelle est la profondeur minimale des sculptures des pneus ?",a:["1 mm","1,6 mm","3 mm"],r:1,e:"1,6 mm est le minimum légal. Pour une bonne tenue sur sol mouillé, mieux vaut ne pas descendre sous 3 mm."},
{t:"vehicule",q:"Les pneus hiver sont-ils obligatoires en Belgique ?",a:["Non, mais ils sont recommandés par temps froid","Oui, du 1er novembre au 31 mars"],r:0,e:"En Belgique, les pneus hiver ne sont pas obligatoires. Ils améliorent nettement l'adhérence sous 7 °C, sur neige et sur verglas."},
{t:"vehicule",q:"Quel document devez-vous avoir avec vous en conduisant ?",a:["Mon permis de conduire","La facture d'achat de la voiture","Le carnet d'entretien"],r:0,e:"À bord : permis de conduire, certificat d'immatriculation et preuve d'assurance, ainsi que le certificat de contrôle technique si le véhicule y est soumis."},
{t:"vehicule",q:"Le témoin rouge de pression d'huile s'allume pendant que vous roulez. Que faites-vous ?",a:["Je m'arrête dès que possible en sécurité et je coupe le moteur","Je continue jusqu'à la fin du trajet","J'accélère pour faire circuler l'huile"],r:0,e:"Un témoin rouge signale un problème grave. Rouler sans pression d'huile peut détruire le moteur."},
{t:"vehicule",q:"Votre voiture a l'ABS. En cas de freinage d'urgence, que faites-vous ?",a:["J'appuie à fond sur la pédale et je maintiens la pression : je peux encore diriger","Je pompe sur la pédale","Je freine doucement pour ne pas bloquer les roues"],r:0,e:"L'ABS empêche les roues de se bloquer : freinez à fond, maintenez la pression et contournez l'obstacle si nécessaire."},
{t:"vehicule",q:"Quel est le numéro d'appel d'urgence européen ?",a:["101","112","117"],r:1,e:"112 : ambulance, pompiers et police, gratuit depuis tout téléphone. Le 101 joint la police."},
{t:"vehicule",q:"Vous arrivez le premier sur un accident avec des blessés. Quelle est la première chose à faire ?",a:["Sécuriser les lieux : feux de détresse, gilet, triangle","Déplacer les blessés vers le bord","Prendre des photos"],r:0,e:"Protéger, alerter (112), secourir : d'abord éviter un suraccident, puis appeler les secours, puis aider les victimes."},
{t:"vehicule",q:"Un blessé est inconscient mais respire normalement. Que faites-vous ?",a:["Je le mets en position latérale de sécurité et je le surveille","Je lui donne à boire","Je le laisse sur le dos sans le surveiller"],r:0,e:"La position latérale de sécurité évite l'étouffement. Restez près de la victime jusqu'à l'arrivée des secours."},
{t:"vehicule",q:"Faut-il retirer le casque d'un motard blessé ?",a:["Non, sauf nécessité absolue (il ne respire plus)","Oui, toujours, pour qu'il respire mieux"],r:0,e:"Retirer un casque peut aggraver une blessure à la colonne vertébrale. Laissez faire les secours, sauf urgence vitale."},
{t:"vehicule",q:"Accident sans blessés, uniquement des dégâts matériels. Que faites-vous ?",a:["Je remplis le constat d'accident avec l'autre conducteur","Je pars sans rien dire si les dégâts sont faibles","J'attends la police dans tous les cas"],r:0,e:"Remplissez ensemble le constat européen d'accident. Quitter les lieux sans laisser vos coordonnées est un délit de fuite."},
{t:"vehicule",q:"Vous accrochez une voiture en stationnement, sans personne autour. Que faites-vous ?",a:["Je laisse mes coordonnées ou je préviens la police","Je pars : personne ne m'a vu","Je repasserai plus tard"],r:0,g:1,e:"Partir sans permettre votre identification est un délit de fuite, sévèrement puni."},
{t:"vehicule",q:"Pour rouler de manière économique, comment passer les vitesses ?",a:["Passer assez tôt au rapport supérieur","Monter haut dans les tours à chaque rapport","Rester en 2e en ville"],r:0,e:"Conduite économique : passer tôt au rapport supérieur, anticiper, rouler de façon souple."},
{t:"vehicule",q:"Des pneus sous-gonflés…",a:["Augmentent la consommation et diminuent la tenue de route","N'ont aucun effet","Améliorent le freinage"],r:0,e:"Contrôlez la pression des pneus à froid, environ une fois par mois."},
{t:"vehicule",q:"Vous attendez plus d'une minute à l'arrêt, par exemple devant un passage à niveau fermé. Que faites-vous ?",a:["Je coupe le moteur","Je laisse tourner le moteur","J'accélère par moments pour garder le moteur chaud"],r:0,e:"Couper le moteur lors d'un arrêt prolongé économise du carburant et réduit la pollution."},
{t:"vehicule",q:"Votre galerie de toit est vide. Que faites-vous ?",a:["Je la retire : elle augmente la consommation","Je la garde, elle n'a aucun effet","Je roule plus vite pour compenser"],r:0,e:"Galerie et coffre de toit augmentent la résistance à l'air, donc la consommation."},

/* ===== Voie publique et permis ===== */
{t:"voie",q:"Qu'est-ce que la chaussée ?",a:["La partie de la voie publique aménagée pour la circulation des véhicules","Toute la largeur de la voie publique, trottoirs compris","La bande de circulation la plus à droite"],r:0,e:"La chaussée est la partie de la voie publique aménagée pour la circulation des véhicules. Trottoirs, accotements et pistes cyclables n'en font pas partie."},
{t:"voie",q:"Une piste cyclable fait-elle partie de la chaussée ?",a:["Non","Oui"],r:0,e:"La piste cyclable est réservée aux cyclistes (et à certains cyclomoteurs). Elle ne fait pas partie de la chaussée."},
{t:"voie",q:"Qu'est-ce qu'une bande de circulation ?",a:["Une subdivision de la chaussée assez large pour une file de véhicules","Une bande réservée aux bus","Le bord du trottoir"],r:0,e:"Une bande de circulation est une partie de la chaussée, matérialisée ou non, qui permet le passage d'une file de véhicules."},
{t:"voie",q:"Où commence une agglomération, au sens du code de la route ?",a:["Au signal portant le nom de la localité (F1)","À la première maison","Au premier feu de signalisation"],r:0,e:"L'agglomération commence au signal F1 et se termine au signal F3. Ce sont ces signaux qui comptent, pas la présence de maisons."},
{t:"voie",q:"Que signifie « céder le passage » ?",a:["Ne pas continuer ma marche si cela oblige d'autres usagers à changer brusquement de direction ou de vitesse","M'arrêter dans tous les cas","Klaxonner pour prévenir les autres"],r:0,e:"Céder le passage, c'est ne pas obliger l'usager prioritaire à freiner ou à dévier brusquement. On ne s'arrête que si c'est nécessaire."},
{t:"voie",q:"Une personne qui pousse son vélo à la main est considérée comme…",a:["Un piéton","Un cycliste","Un conducteur de véhicule"],r:0,e:"Une personne qui conduit un vélo à la main est assimilée à un piéton."},
{t:"voie",q:"Sur une chaussée à double sens, où devez-vous circuler ?",a:["Le plus près possible du bord droit","Au milieu de la chaussée","N'importe où si la route est libre"],r:0,e:"Tout conducteur circule aussi près que possible du bord droit de la chaussée, en gardant une distance suffisante avec les usagers qui s'y trouvent."},
{t:"voie",q:"À quel âge minimum peut-on obtenir le permis de conduire B ?",a:["16 ans","17 ans","18 ans"],r:2,e:"Le permis B s'obtient à 18 ans. L'apprentissage peut commencer plus tôt, selon les règles de votre Région."},
{t:"voie",q:"Avec le permis B, vous pouvez conduire un véhicule dont la masse maximale autorisée ne dépasse pas…",a:["3 500 kg","5 000 kg","7 500 kg"],r:0,e:"Catégorie B : masse maximale autorisée de 3 500 kg."},
{t:"voie",q:"Un véhicule de catégorie B peut compter au maximum combien de places assises, conducteur compris ?",a:["5","9","12"],r:1,e:"Catégorie B : 8 passagers au maximum en plus du conducteur, soit 9 places."},
{t:"voie",q:"Avec le permis B, quelle remorque pouvez-vous toujours tracter ?",a:["Une remorque de 750 kg maximum (masse maximale autorisée)","Une remorque de 2 000 kg","N'importe quelle remorque si la voiture est assez puissante"],r:0,e:"Une remorque légère (750 kg maximum) est toujours permise. Au-delà, l'ensemble ne doit pas dépasser 3 500 kg ; sinon il faut le code 96 ou le permis BE."},
{t:"voie",q:"Le code de la route s'applique-t-il aussi aux piétons ?",a:["Oui","Non"],r:0,e:"Le code de la route s'applique à tous les usagers : piétons, cyclistes, conducteurs…"}
];
